import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.LJP3gfxI.js";const p=JSON.parse('{"title":"SQLiteDatabase — takoform_sqlite_database","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/sqlite-database.md","filePath":"proposals/edge/sqlite-database.md"}'),r={name:"proposals/edge/sqlite-database.md"};function s(n,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="sqlitedatabase-—-takoform-sqlite-database" tabindex="-1">SQLiteDatabase — <code>takoform_sqlite_database</code> <a class="header-anchor" href="#sqlitedatabase-—-takoform-sqlite-database" aria-label="Permalink to &quot;SQLiteDatabase — `takoform_sqlite_database`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A worker keeps relational application state — accounts, jobs, inventories — in one embedded SQLite database. Workers consume it through <code>module-worker.sqlite</code> bindings.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The database has no desired fields; SQLite semantics are the identity, not a configuration.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>Exactly the <code>edge.sql@1.0.0</code> contract: execute/query/transaction with bound parameters, SQLite&#39;s SQL dialect and dynamic typing, rollback-only queries, serializable transactions applying atomically over a single consistent snapshot, <code>busy</code> under write contention, and closed errors.</p><p><code>EdgeSqlValue</code> is null, a finite binary64 number inside <code>Number.MAX_SAFE_INTEGER</code>, a UTF-8 string, or the common canonical <code>{&quot;encoding&quot;:&quot;base64&quot;,&quot;data&quot;:&quot;...&quot;}</code> bytes object. Boolean, bigint, and SQL-only tagged objects are not values. SQLite may store a number as INTEGER or REAL, but the binding does not expose that storage-class distinction. Unsafe input or output is <code>numeric_out_of_range</code>; a host never rounds or stringifies it. A result is exactly <code>rows</code> plus <code>rowsWritten</code>; inserted identities use SQL <code>RETURNING</code>, not <code>lastInsertRowId</code>.</p><p><code>execute</code> runs one effectful, non-idempotent statement. <code>query</code> runs one statement in a rollback-only transaction, materializes its result, always rolls back, returns <code>rowsWritten: 0</code>, and leaves no persistent effect without trying to classify the SQL as read-only. <code>transaction</code> runs 1 through 100 statements under serializable all-or-none isolation and materializes every result before commit. Runtime calls reject multiple statements, transaction-control SQL, and durable schema changes. Schema history is applied only through <code>SQLiteMigrationApplication</code> (<a href="./../../spec/decisions/0034-edge-sql-uses-safe-wire-values-and-rollback-only-queries.html">decision 0034</a>).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>SQL dialect, typing, and isolation are what application code is written against. An <code>engine</code> token selecting SQLite versus other engines would make one desired document mean different systems on different hosts — exactly what decision 0008 prohibits.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A Postgres or MySQL database is a different Form in a managed-database family. Migration bytes and applying their ordered history are separate <code>SQLiteMigrationSet</code> and <code>SQLiteMigrationApplication</code> resources; the database identity does not absorb schema rollout policy, and the runtime Interface cannot bypass their append-only ledger.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>edge.sql@1.0.0</code>.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; it is a binding target (<code>module-worker.sqlite</code>).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a database bound by any Worker Version must fail with <code>dependency_in_use</code>. Delete destroys the data; portable state never carries backups or connection material.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The embedded per-application SQLite database of a proven edge platform. The retained v1alpha2 <code>RelationalDatabase</code> candidate, whose open <code>engine</code> token this Form replaces by fixing SQLite as the shape.</p>',21)])])}const b=a(r,[["render",s]]);export{p as __pageData,b as default};
